import{_ as t,o as s,c as e,a6 as n}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"商品事实与素材简报","description":"","frontmatter":{"id":"product-brief","title":"商品事实与素材简报","chapter":"03","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["footwear-skills"],"order":20,"content_kind":"操作教程"},"headers":[],"relativePath":"ecommerce/product-brief.md","filePath":"ecommerce/product-brief.md"}'),p={name:"ecommerce/product-brief.md"};function d(i,a,r,l,o,c){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="商品事实与素材简报-做完才能开始套图" tabindex="-1">商品事实与素材简报，做完才能开始套图 <a class="header-anchor" href="#商品事实与素材简报-做完才能开始套图" aria-label="Permalink to &quot;商品事实与素材简报，做完才能开始套图&quot;">​</a></h1><p>本节做出三份可直接使用的东西，一张商品事实表、一份照片索引和一张图片任务表。它们分别回答商品是什么、哪张图能证明、每张成品图要讲什么。后面的<a href="./image-set">套图教程</a>沿用原稿的便携榨汁杯，跨境专项则使用明确标为虚构的DN01收纳盒练习。</p><h2 id="把-产品介绍-改成能核对的事实" tabindex="-1">把“产品介绍”改成能核对的事实 <a class="header-anchor" href="#把-产品介绍-改成能核对的事实" aria-label="Permalink to &quot;把“产品介绍”改成能核对的事实&quot;">​</a></h2><p>拿商品说明书、规格表、实拍和实际发货清单逐项填写。卖点“易清洗”还不够，补充哪些部件能拆、哪部分可以水洗、操作依据在哪里。没有依据的“食品级”“无线充电”“安全锁”先留空，原稿出现过这些词也不能直接拿给自己的商品使用。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SKU：JB01-white（练习ID）</span></span>
<span class="line"><span>产品：便携榨汁杯</span></span>
<span class="line"><span>商品颜色：以本SKU实拍为准</span></span>
<span class="line"><span>杯体、盖子、底座、按钮外观：见front和side照片</span></span>
<span class="line"><span>尺寸/容量/功率/充电方式：填写真实规格及来源，缺失留空</span></span>
<span class="line"><span>实际发货：逐项写商品、配件、数量；拍一张平铺照片</span></span>
<span class="line"><span>适用场景：经确认可使用的厨房/办公室等</span></span>
<span class="line"><span>使用与清洗：按说明书写动作，标出不能冲洗的部位</span></span>
<span class="line"><span>可使用的文字：产品名、已证实的功能和参数</span></span>
<span class="line"><span>本次不写：没有证明的认证、效率、健康功效与比较结论</span></span></code></pre></div><h2 id="按图片职责补拍" tabindex="-1">按图片职责补拍 <a class="header-anchor" href="#按图片职责补拍" aria-label="Permalink to &quot;按图片职责补拍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件名示例</th><th>怎样拍</th><th>用在哪里</th></tr></thead><tbody><tr><td>JB01_white_front.jpg</td><td>完整正面，杯盖和底座不截断</td><td>白底图、场景合成</td></tr><tr><td>JB01_white_side.jpg</td><td>侧面光线均匀，避免广角</td><td>比例与结构核对</td></tr><tr><td>JB01_white_lid.jpg</td><td>杯盖局部有足够清晰度</td><td>真实细节展示</td></tr><tr><td>JB01_white_parts.jpg</td><td>实际发货物平铺</td><td>配件图</td></tr><tr><td>JB01_white_dimensions.csv</td><td>测量值、单位、测量对象、来源</td><td>尺寸图</td></tr><tr><td>JB01_white_steps_01.jpg</td><td>说明书允许的实际动作</td><td>使用步骤图</td></tr></tbody></table><p>不要把一张正面图扩成背面、刀头和内部结构照片。原图不能证明的区域，任务表写“补拍”，先制作已有素材支持的图片。</p><h2 id="让助手整理分工-别让它补事实" tabindex="-1">让助手整理分工，别让它补事实 <a class="header-anchor" href="#让助手整理分工-别让它补事实" aria-label="Permalink to &quot;让助手整理分工，别让它补事实&quot;">​</a></h2><p>上传真实规格与照片索引后，可复制下面的整理提示词给文字助手。它的产物是表格和文案草稿，不是商品照片。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据我上传的商品资料，整理JB01的视觉制作简报。分别输出商品事实表、照片索引、六张商品图任务表。</span></span>
<span class="line"><span>事实表保留数值、单位和资料出处；图片只能作为可见外观依据。资料没有写的容量、材质等级、充电方式、安全结构、认证，写“未提供”，不要按同类产品推测。</span></span>
<span class="line"><span>任务表每张写用途、买家问题、所需照片、构图、准确文案、不得出现的内容。每张只解释一个主要问题。缺照片的任务标为待补拍，提供已有素材可做的替代任务。</span></span>
<span class="line"><span>竞品图只分析信息顺序和构图，不复制其文字、标识和独特包装。输出供我逐项核对的表格，不直接生图。</span></span></code></pre></div><h2 id="看一条卖点有没有写实" tabindex="-1">看一条卖点有没有写实 <a class="header-anchor" href="#看一条卖点有没有写实" aria-label="Permalink to &quot;看一条卖点有没有写实&quot;">​</a></h2><p>“随手清洗，告别烦恼”无法判断结构和方法。若说明书确认杯体可拆、底座不能入水，可改成“杯体拆下单独清洗”，配一张真实拆开后的照片，并把不能水洗的底座说明放在同屏。画面、短文案和操作要求对应同一个事实，读者才能照着做。</p><p>事实表确认后，再安排<a href="./image-set">六张套图</a>。有多个颜色时先各拍一张同角度商品照片，后续换商品层，不能把白色图片一键染成绿色就当作真实SKU。</p>`,14)])])}const u=t(p,[["render",d]]);export{_ as __pageData,u as default};
